operation.add:
if (!empty($data['filter_promo_id'])) {
    $this->load->model('catalog/promo');
    $promo_product_ids = $this->model_catalog_promo->getPromoProductIds($data['filter_promo_id']);
    if ($promo_product_ids) {
        $sql .= " AND p.product_id IN (" . implode(',', $promo_product_ids) . ")";
    } else {
        $sql .= " AND p.product_id = -1";
    }
}

if (isset($this->request->get['promo_id']) && is_string($sql) && stripos($sql, 'product p') !== false && stripos($sql, 'p.product_id IN') === false) {
    $this->load->model('catalog/promo');
    $promo_product_ids = $this->model_catalog_promo->getPromoProductIds((int)$this->request->get['promo_id']);
    $promo_cond = $promo_product_ids ? " p.product_id IN (" . implode(',', array_map('intval', $promo_product_ids)) . ") " : " p.product_id = -1 ";

    // Нейтрализуем "category_id = 0", из-за которого прячется ползунок цены
    $sql = str_replace("p2c.category_id = '0'", "1=1", $sql);
    $sql = str_replace("p2c.category_id = 0", "1=1", $sql);

    // Хирургически вставляем наше условие, не ломая структуру SQL
    if (stripos($sql, 'WHERE') !== false) {
        $sql = preg_replace('/WHERE/i', 'WHERE ' . $promo_cond . ' AND ', $sql, 1);
    } else {
        if (preg_match('/(GROUP BY|ORDER BY|LIMIT)/i', $sql, $matches, PREG_OFFSET_CAPTURE)) {
            $sql = substr_replace($sql, ' WHERE ' . $promo_cond . ' ', $matches[0][1], 0);
        } else {
            $sql .= ' WHERE ' . $promo_cond;
        }
    }
}

if (isset($this->request->get['promo_id']) && is_string($sql) && stripos($sql, 'product p') !== false && stripos($sql, 'p.product_id IN') === false) {
    $this->load->model('catalog/promo');
    $promo_product_ids = $this->model_catalog_promo->getPromoProductIds((int)$this->request->get['promo_id']);
    $promo_cond = $promo_product_ids ? " p.product_id IN (" . implode(',', array_map('intval', $promo_product_ids)) . ") " : " p.product_id = -1 ";

    $sql = str_replace("p2c.category_id = '0'", "1=1", $sql);
    $sql = str_replace("p2c.category_id = 0", "1=1", $sql);

    if (stripos($sql, 'WHERE') !== false) {
        $sql = preg_replace('/WHERE/i', 'WHERE ' . $promo_cond . ' AND ', $sql, 1);
    } else {
        if (preg_match('/(GROUP BY|ORDER BY|LIMIT)/i', $sql, $matches, PREG_OFFSET_CAPTURE)) {
            $sql = substr_replace($sql, ' WHERE ' . $promo_cond . ' ', $matches[0][1], 0);
        } else {
            $sql .= ' WHERE ' . $promo_cond;
        }
    }
}
